    private void require(boolean condition,String message){if(!condition)throw new AssertionError(message);checks++;android.util.Log.i("TaimAccessTest","check "+checks+": "+message);}
    private AccessibilityNodeInfo findIn(AccessibilityNodeInfo root,String label){if(root==null)return null;if(label.contentEquals(root.getText()==null?"":root.getText())||label.contentEquals(root.getHintText()==null?"":root.getHintText())||label.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()))return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo n=findIn(root.getChild(i),label);if(n!=null)return n;}return null;}
    private AccessibilityNodeInfo find(String label){return findIn(getUiAutomation().getRootInActiveWindow(),label);}
    private AccessibilityNodeInfo waitNode(String label)throws Exception{long end=SystemClock.uptimeMillis()+15000;do{AccessibilityNodeInfo node=find(label);if(node!=null)return node;Thread.sleep(100);}while(SystemClock.uptimeMillis()<end);throw new AssertionError("Missing "+label);}
