    private View virtual(View root){if(root.getClass().getSimpleName().equals("TaimAccessibility"))return root;if(root instanceof ViewGroup){ViewGroup g=(ViewGroup)root;for(int i=0;i<g.getChildCount();i++){View result=virtual(g.getChildAt(i));if(result!=null)return result;}}return null;}
